#!/usr/bin/env python3
"""Turn 35 Wave 84: THE OVERWRITE HAZARD, AND THE MOST DANGEROUS FABRICATION YET.

Wave 84's centrepieces:

1. THE OVERWRITE HAZARD, which the corpus did not carry and which is the single most
   important account fact in the whole corpus. Two independent failure reports describe the
   same mechanism: a fresh profile created after a reinstall **overwrites** the old one, and
   connecting a Google or Apple account that already holds a profile **deletes current
   progress**. The corpus had the official "we cannot guarantee recovery" line and the
   sign-out warning, but not the overwrite direction - and the overwrite is what actually
   destroys accounts.

2. THE LINK CAN SILENTLY DROP. A player who lost years of progress reports checking "the
   Google sign-in was disabled in the settings (which happened randomly)" and re-linking
   whenever he saw it. So the check is not once - it is every session, and above all
   immediately before any uninstall.

3. PLAYDREAMLEAGUESOCCER.COM REJECTED A SEVENTH TIME - and this is the most dangerous
   fabrication in the register, because it is a **backup procedure that does not exist**:
   "Settings > Cloud > Save Progress." Following it would give a player false confidence
   while their real profile sat unlinked. Rejections one through six were bad; this one is
   a data-loss instruction.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w84')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_ac=new_ev("support.ftgames.com 214387685 'How do I backup/restore/transfer my save data?' (OFFICIAL - linking is manual, not automatic; unlinked profiles cannot be guaranteed recoverable; save data is NOT secured on Google Play Games or iCloud; save data and IAP cannot be transferred across platforms; Facebook and Game Center are unsupported), support.ftgames.com 4413273241873 'How is save data stored and transferred in DLS?' (OFFICIAL - the one-account rule, the Options > Advanced > Manage Devices / Link Profile navigation, the cross-platform code recommendation, the do-not-share-codes warning, the sign-out warning), r/DreamLeagueSoccer 1kg9sem 'I lost my Dream League Soccer account due to poor save system' (6 May 2025 - the overwrite hazard and the silently dropping link), r/DreamLeagueSoccer 1e42udi 'Precautions to make sure your DLS data is saved' (15 Jul 2024 - the pre-transfer check procedure and the override warning), r/DreamLeagueSoccer 1mokoql (12 Aug 2025 - the FTG support recovery route and the persistent server-side ID), r/DreamLeagueSoccer 1g0u2ru 'Restore account' (10 Oct 2024 - current progress is deleted when the connected account holds older data), r/DreamLeagueSoccer 16vliig (29 Sep 2023 - 'this game does not have a cloud save', superseded), sakibpro.com transfer guide (14 Dec 2025 - the full Android and iOS procedures, the 5-minute code, the max-3-devices figure, and the statement that manual folder-copy backup no longer works), oyuncozumleri.com (11 Oct 2026, Turkish - a method-validity table: Sign in with Google valid Android-only, Sign in with Apple valid iOS 13.0+, Generate Code valid and officially recommended for platform changes, Google Play Games invalid), playdreamleaguesoccer.com (REJECTED A SEVENTH TIME - a fabricated 'Settings > Cloud > Save Progress' backup path), App Store DLS26 version history (OFFICIAL - the 13.110 and 13.120 release notes), r/DreamLeagueSoccer 1rf90a7 (26 Feb 2026 - the 12th Man vote opens), r/DreamLeagueSoccer 1pdeilk (3 Dec 2025 - Raphinha and Alvarez revealed as Kick-Off Stars), r/DreamLeagueSoccer 1pl7a5b (13 Dec 2025 - the Season Pass forces a choice between them), r/DreamLeagueSoccer 1p9rgzl (29 Nov 2025 - the event-card acquisition routes), fifaworldcupnews.com DLS26 features (23 Jul 2026 - Kick-Off Stars as a starting 11 across Seasons 1 and 2, DOWNGRADED), YouTube DLS26 event titles (Win Streak Event, Festival Vase Event, Dynamic Stars Tournament)",
    "THE OVERWRITE HAZARD, THE SILENTLY DROPPING LINK, THE RECOVERY ROUTE, AND THE SEVENTH REJECTION. (1) THE OVERWRITE HAZARD, the wave's most important finding and absent from the corpus: 'I made the mistake of uninstalling the 2024 version without rechecking the account link. But when I reinstalled the game, my original account was gone. I was met with a fresh profile, and **worse, it seems that this new empty account overwrote my old one.** Just like that - years of progress lost.' A second report gives the other direction: '**Current progress will be deleted if the Google account you connect has the old data saved.**' And a third gives the pre-condition: '**Make sure no previous profile is connected to your Apple ID before you connect it, as it will override the data if there's an existing profile already.**' So the hazard runs BOTH ways - a new profile can overwrite an old one, and connecting an account that holds a profile can delete what is on the device now. The corpus carried the official 'we cannot guarantee that it can be recovered' line and the sign-out warning, but not the overwrite direction, and the overwrite is what actually destroys accounts. (2) THE LINK CAN SILENTLY DROP: the same player reports that 'whenever I noticed that **the Google sign-in was disabled in the settings (which happened randomly)**, I would re-link it immediately to avoid losing progress.' So the check is not a one-time setup step - it is every session, and above all immediately before any uninstall or device change. (3) THE PRE-TRANSFER CHECK PROCEDURE: on iOS, go to Apple ID settings, 'Sign-in & Security', then 'sign in with Apple' and confirm no previous profile is attached. On Android, open the signed-in-with-Google setting and 'if it shows DLS24, remove it and then login with your Google account in the game so that you can be sure the data won't be overwritten.' (4) THE RECOVERY ROUTE: the account ID persists server-side - 'unless you don't delete your account, the id is always stays on FTG server' - so support can recover it. What to send FTG: 'everything you know about your player, their rating, your name, rank, phone name, if you have a screenshot of your manage device id.' (5) THE SEVENTH REJECTION, and the most dangerous fabrication in the register: playdreamleaguesoccer.com instructs players to 'Use the Cloud Save feature linked to your Google Play or Game Center account. Go to Settings > Cloud > Save Progress.' **No such path exists** - the official articles state the opposite, that Google Play Games and Game Center are NOT used for save data. A player following it would believe they were backed up while their profile sat unlinked. Rejections one to six were bad; this one is a data-loss instruction. (6) A METHOD-VALIDITY TABLE from a Turkish source, corroborating the official position independently: Sign in with Google = valid, Android only; Sign in with Apple = valid, iOS 13.0+; Generate Code = valid and officially recommended when changing platform; Google Play Games = invalid. (7) SAKIBPRO adds that manual backup 'no longer works': 'Old manual backup tricks - copying the com.firsttouchgames.dls7 folder or using file explorers - no longer work. DLS 26 stores all game data securely online and validates every login through its servers.' This closes the save-tampering question definitively. (8) THE KICK-OFF STARS SEASON PASS CHOICE: 'Kick off stars Raphinha and Alvarez are here in season pass, **but you can only choose one of them.**' So the pass forces a real decision between the two launch cards. (9) THE EVENT-CARD ACQUISITION ROUTES, consolidated: Dream Stars were gained 'by dream agents; via dll live events, season passes and by purchasing with irl money' - four routes, and the same four apply to Kick-Off Stars. (10) KICK-OFF STARS ARE A STARTING 11: 'full starting 11 potential for Seasons 1 & 2' - so the collection spans two seasons rather than one event (downgraded source). (11) THE 12TH MAN WAS ADDED TO THE COLLECTION, per the official version history: 'The DLS community has voted, and we've added this extra superstar to the collection.' The corpus records that FTG never NAMED the player; this confirms the addition without naming them. (12) THE DLS26 EVENT CALENDAR, from creator coverage: a Win Streak Event (free coins plus Dream Star player rewards), a Festival Vase Event, and a Dynamic Stars Tournament. (13) A VERSION-ATTRIBUTION NOTE: the App Store's 13.110 block carries 'Increased squad size - Now with unlimited special players in your club', while the corpus dates unlimited specials to launch and to Summer Spotlight. The store blocks are ambiguous in ordering, so this is recorded as an attribution discrepancy rather than a correction.",
    "THE OVERWRITE HAZARD, the corpus's most important missing account fact: a fresh profile created after a reinstall OVERWRITES the old one, and connecting a Google or Apple account that already holds a profile DELETES current progress - the hazard runs both ways. THE LINK CAN SILENTLY DROP, so check the sign-in state every session and always immediately before an uninstall or device change. THE PRE-TRANSFER CHECK: confirm no previous profile is attached to your Apple ID, and remove any stale game entry from the Google setting first. THE RECOVERY ROUTE: the account ID persists on FTG's servers, so support can recover it - send them the player rating, your name, rank, phone name and a screenshot of the Manage Device ID. THE SEVENTH REJECTION and the most dangerous yet: playdreamleaguesoccer.com's fabricated 'Settings > Cloud > Save Progress' backup path, which does not exist. Manual folder-copy backup no longer works - DLS26 validates every login server-side. THE KICK-OFF STARS SEASON PASS FORCES A CHOICE between Raphinha and Alvarez. Event cards come from four routes: agents, DLL live events, season passes and real money.",
    "THE OVERWRITE HAZARD, THE SILENTLY DROPPING LINK, AND THE SEVENTH REJECTION",
    quality="official")

add_claim("THE OVERWRITE HAZARD, the corpus's most important missing account fact: a fresh profile created after a reinstall **overwrites** the old one. 'I made the mistake of uninstalling the 2024 version without rechecking the account link. But when I reinstalled the game, my original account was gone. I was met with a fresh profile, and **worse, it seems that this new empty account overwrote my old one.** Just like that - years of progress lost.'", 2, "account/overwrite-hazard-fresh-profile", [e_ac], notes="Absent from the corpus until now; the mechanism that actually destroys accounts")
add_claim("THE OVERWRITE RUNS THE OTHER WAY TOO: '**Current progress will be deleted if the Google account you connect has the old data saved**' - and '**Make sure no previous profile is connected to your Apple ID before you connect it, as it will override the data if there's an existing profile already.**' So both a new profile and a connecting account can destroy data, in opposite directions.", 2, "account/overwrite-hazard-connecting-account", [e_ac])
add_claim("THE LINK CAN SILENTLY DROP: a player who lost years of progress reports checking 'the Google sign-in was disabled in the settings (**which happened randomly**)' and re-linking whenever he saw it. **So the account check is not a one-time setup step - it is every session, and above all immediately before any uninstall or device change.**", 2, "account/link-drops-silently", [e_ac], notes="Turns the corpus's 'link it once' advice into a standing check")
add_claim("THE PRE-TRANSFER CHECK PROCEDURE: on iOS, go to Apple ID settings > 'Sign-in & Security' > 'sign in with Apple' and confirm no previous profile is attached. On Android, open the signed-in-with-Google setting and 'if it shows DLS24, remove it and then login with your Google account in the game so that you can be sure the data won't be overwritten.'", 2, "account/pre-transfer-check-procedure", [e_ac])
add_claim("THE RECOVERY ROUTE: the account ID persists server-side - 'unless you don't delete your account, the id is always stays on FTG server' - so support can recover a lost profile. What to send FTG: 'everything you know about your player, their rating, your name, rank, phone name, if you have a screenshot of your manage device id.'", 3, "account/ftg-support-recovery-route", [e_ac])
add_claim("REJECTED A SEVENTH TIME, and this is the most dangerous fabrication in the register: playdreamleaguesoccer.com instructs players to 'Use the Cloud Save feature linked to your Google Play or Game Center account. **Go to Settings > Cloud > Save Progress.**' **No such path exists** - the official articles state the opposite, that Google Play Games and Game Center are NOT used for save data. A player following it would believe they were backed up while their profile sat unlinked. Rejections one to six were bad; this one is a data-loss instruction.", 4, "errata/playdream-seventh-rejection-fake-backup-path", [e_ac], notes="Seventh rejection; the first that could directly cause data loss")
add_claim("A METHOD-VALIDITY TABLE corroborating the official position from an independent source: **Sign in with Google = valid, Android only** · **Sign in with Apple = valid, iOS 13.0+** · **Generate Code = valid and officially recommended when changing platform** · **Google Play Games = invalid.**", 3, "account/method-validity-table", [e_ac])
add_claim("MANUAL BACKUP NO LONGER WORKS: 'Old manual backup tricks - copying the com.firsttouchgames.dls7 folder or using file explorers - no longer work. **DLS 26 stores all game data securely online and validates every login through its servers.**' This closes the corpus's save-tampering question definitively - there is no local file to tamper with.", 3, "account/manual-backup-no-longer-works", [e_ac], notes="Closes the save-tampering line of inquiry outright")
add_claim("THE KICK-OFF STARS SEASON PASS FORCES A CHOICE: 'Kick off stars Raphinha and Alvarez are here in season pass, **but you can only choose one of them.**' So the pass is not a bundle - it is a decision between the two launch cards, and the unchosen one is gone for that pass.", 3, "seasonpass/kick-off-stars-forced-choice", [e_ac])
add_claim("THE EVENT-CARD ACQUISITION ROUTES, consolidated from the DLS25 Dream Stars precedent: 'we were able to gain these dream stars by **dream agents; via dll live events, season passes and by purchasing with irl money**.' Four routes, and the same four apply to Kick-Off Stars - so an event card is obtainable without money, but only through several systems at once.", 3, "cards/event-card-acquisition-routes", [e_ac])
add_claim("KICK-OFF STARS ARE A STARTING 11, not a pair: 'full starting 11 potential for Seasons 1 & 2' - so the collection spans two seasons rather than one launch event, with Raphinha and Alvarez as the first two named. Downgraded source, but the shape matters for planning.", 3, "cards/kick-off-stars-starting-11-two-seasons", [e_ac])
add_claim("THE 12TH MAN WAS ADDED TO THE COLLECTION, per the official version history: 'The DLS community has voted, and we've added this extra superstar to the collection.' The corpus records that FTG never NAMED the player; this confirms the addition happened without naming them.", 2, "12thman/added-to-collection-confirmed", [e_ac])
add_claim("THE DLS26 EVENT CALENDAR, from creator coverage: a **Win Streak Event** (free coins plus Dream Star player rewards), a **Festival Vase Event**, and a **Dynamic Stars Tournament**. So the rotating-event surface has at least three named formats beyond the cups.", 3, "events/dls26-event-calendar-names", [e_ac])
add_claim("VERSION-ATTRIBUTION NOTE: the App Store's 13.110 block carries 'Increased squad size - Now with unlimited special players in your club', while the corpus dates unlimited specials to launch and to Summer Spotlight. The store blocks are ambiguous in ordering, so this is recorded as an attribution discrepancy, not a correction - the same release-date unreliability already logged at C-023.", 4, "errata/unlimited-specials-version-attribution", [e_ac])

for p in ['EV-497_overwrite_hazard.html','EV-497b_account_recovery.html','EV-497c_kick_off_stars_and_12th_man.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
